import math

def D(n):
    """Calculates the divisor D(n) = n^3 + 4n^2 + 6n + 4."""
    return n**3 + 4*n**2 + 6*n + 4

def is_power_of(k, base):
    """Checks if k is a power of base (where base > 1)."""
    if k <= 0:
        return False
    if k == 1 and base != 1:
        return True
    while k > 1:
        if k % base != 0:
            return False
        k //= base
    return True

# Search for small non-negative integers n where D(n) is a power of 2 or 5.
limit = 50
print(f"Searching for n in [0, {limit}] where D(n) is a power of 2 or 5.\n")
results_2 = []
results_5 = []

for n in range(limit + 1):
    d_n = D(n)

    if d_n > 1:
        is_p2 = is_power_of(d_n, 2)
        is_p5 = is_power_of(d_n, 5)

        if is_p2:
            results_2.append((n, d_n))
        elif is_p5:
            results_5.append((n, d_n))

print("--- Results where D(n) is a power of 2 ---")
if results_2:
    for n, d_n in results_2:
        print(f"n = {n}, D(n) = {d_n} = 2^{int(math.log2(d_n))}")
else:
    print("No solutions found in this range.")

print("\n--- Results where D(n) is a power of 5 ---")
if results_5:
    for n, d_n in results_5:
        print(f"n = {n}, D(n) = {d_n} = 5^{int(math.log5(d_n))}")
else:
    print("No solutions found in this range.")

def calculate_D(n):
    """Calculates D(n) = n^3 + 4n^2 + 6n + 4."""
    return n**3 + 4*n**2 + 6*n + 4

def check_divisibility(n):
    """Checks if 20^(n+1) is divisible by D(n)."""
    D_n = calculate_D(n)

    # Handle the case where D(n) might be zero (though for n >= 0, D(n) >= 4)
    if D_n == 0:
        return "Undefined (D(n) is 0)", False

    try:
        numerator = 20**(n+1)
        if numerator % D_n == 0:
            return f"Yes (20^{n+1} is divisible by {D_n})", True
        else:
            return f"No (20^{n+1} is not divisible by {D_n})", False
    except OverflowError:
        # If numbers are too large, rely on modular arithmetic checks (or skip if the task implies small calculation)
        # For the range n=0 to n=6, standard Python integers should handle this.
        return f"Calculation error for large numbers, D(n)={D_n}", False

results = {}
for n in range(7):
    result, is_divisible = check_divisibility(n)
    results[n] = {"D(n)": calculate_D(n), "Divisible": is_divisible, "Result": result}

for n, data in results.items():
    print(f"n={n}: D(n)={data['D(n)']}, Divisible={data['Divisible']}, Result={data['Result']}")

