import sympy

def D(n):
    """Calculates D(n) = n^3 + 4n^2 + 6n + 4."""
    return n**3 + 4*n**2 + 6*n + 4

def check_D_prime_factors(n):
    """
    Checks if D(n) is comprised solely of factors 2 and 5.
    Returns True if it is, False otherwise, along with D(n).
    """
    d_n = D(n)
    if d_n == 0:
        return False, 0 # Should not happen for n >= 0

    factors = sympy.factorint(d_n)

    for p in factors:
        if p not in [2, 5]:
            return False, d_n

    return True, d_n

# Candidates provided: n=7, 9, 11, 13, 15.
# Checking up to n=21 to provide a more robust test.
candidates = [7, 9, 11, 13, 15, 17, 19, 21]

results = {}
print("--- Results of D(n) Prime Factor Check ---")
for n in candidates:
    is_2_5_powered, d_n = check_D_prime_factors(n)
    results[n] = (is_2_5_powered, d_n)
    print(f"n={n}: D({n}) = {d_n}. Is D(n) 2^a 5^b? {is_2_5_powered}")

print("\n--- Summary ---")
for n, (is_2_5_powered, d_n) in results.items():
    if not is_2_5_powered:
        # Find the smallest non-2/5 prime factor for better reporting
        try:
            factors = sympy.factorint(d_n)
            smallest_other_prime = min([p for p in factors if p not in [2, 5]])
            print(f"n={n}: Fails the prime factor test. Smallest other prime factor: {smallest_other_prime}")
        except Exception:
            print(f"n={n}: Fails the prime factor test (details unavailable).")

